@prefix sh:   <http://www.w3.org/ns/shacl#> .
@prefix rdf:  <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
@prefix xsd:  <http://www.w3.org/2001/XMLSchema#> .
@prefix nltl: <https://w3id.org/nltl/vocab#> .
@prefix qudt: <http://qudt.org/schema/qudt/> .
@prefix unit: <http://qudt.org/vocab/unit/> .

# -----------------------------------------------------------------
# Shape: QuantityValue – represents the corrosion/abrasion addition
# -----------------------------------------------------------------
_:QuantityValueShape
    a sh:NodeShape ;
    rdfs:comment "QuantityValue node that must encode the corrosion/abrasion addition as exactly 1.0 mm per I2‑11.3. Units and datatype are fixed by the locked representation context." ;
    sh:property [
        sh:path qudt:numericValue ;
        sh:datatype xsd:decimal ;
        sh:minInclusive "1.0"^^xsd:decimal ;
        sh:maxInclusive "1.0"^^xsd:decimal ;
        rdfs:comment "Numeric value must be exactly 1.0 (decimal), per the source requirement." ;
    ] ;
    sh:property [
        sh:path qudt:unit ;
        sh:hasValue unit:MilliM ;
        rdfs:comment "Unit must be the canonical QUDT millimetre unit." ;
    ] .

# -----------------------------------------------------------------
# Shape: Ship – applies the corrosion/abrasion addition requirement
# -----------------------------------------------------------------
_:ShipCorrosionAbrasionAdditionShape
    a sh:NodeShape ;
    sh:targetClass nltl:ship ;
    rdfs:comment """This shape encodes the requirement from I2‑11.3:
    “Polar Class ships are to have a minimum corrosion/abrasion addition of ts = 1.0 mm applied to all internal structures within the ice‑strengthened hull areas…”.

    The applicability to Polar‑Class ships is recorded in the source but the exact activation
    (e.g., presence/true value of nltl:polarClassRequirementsApplicable) is ambiguous in the supplied data.
    Consequently, this shape validates the numeric/units constraints for every ship instance; callers may
    apply additional filtering based on their own eligibility assertions.
    """ ;
    sh:property [
        # Path: ship → internalIceStrengthenedStructure → corrosion addition quantity value
        sh:path ( nltl:hasInternalIceStrengthenedStructure nltl:internalStructureCorrosionAbrasionAddition ) ;
        sh:node _:QuantityValueShape ;
        rdfs:comment "Each internal ice‑strengthened structure linked from a ship must have an associated corrosion/abrasion addition matching the QuantityValueShape." ;
    ] .

