# -----------------------------------------------------------------
# Shape: Ship – applies the corrosion/abrasion addition requirement
# -----------------------------------------------------------------
_:ShipCorrosionAbrasionAdditionShape
    a sh:NodeShape ;
    sh:targetClass nltl:ship ;
    rdfs:comment """
    This shape encodes the requirement from I2‑11.3:
    “Polar Class ships are to have a minimum corrosion/abrasion addition of ts = 1.0 mm applied to all internal structures within the ice‑strengthened hull areas…”.

    The applicability to Polar‑Class ships is recorded in the source but the exact activation condition
    (e.g., presence/true value of nltl:polarClassRequirementsApplicable) is ambiguous in the supplied data.
    Consequently, this shape validates the numeric/units constraints for every ship instance; callers may
    apply additional filtering based on their own eligibility assertions.
    """ ;
    sh:property [
        # Path: ship → internalIceStrengthenedStructure → corrosion addition quantity value
        sh:path ( nltl:hasInternalIceStrengthenedStructure nltl:internalStructureCorrosionAbrasionAddition ) ;
        sh:node _:QuantityValueShape ;
        rdfs:comment "Each internal ice‑strengthened structure linked from a ship must have an associated corrosion/abrasion addition matching the QuantityValueShape." ;
    ] .

# -----------------------------------------------------------------
# Shape: InternalIceStrengthenedStructure – optional sanity check
# -----------------------------------------------------------------
_:InternalIceStrengthenedStructureShape
    a sh:NodeShape ;
    sh:targetClass nltl:internalIceStrengthenedStructure ;
    rdfs:comment "Internal ice‑strengthened structures should be linked from a ship via nltl:hasInternalIceStrengthenedStructure. No further constraints are required beyond the QuantityValueShape enforced on the ship." ;
    sh:property [
        sh:path nltl:internalStructureCorrosionAbrasionAddition ;
        sh:nodeKind sh:BlankNodeOrIRI ;
        rdfs:comment "The corrosion abrasion addition property must point to a QuantityValue (validated by the QuantityValueShape)." ;
    ] .

